+/**
+ * Runs an agent until it completes. A delegate_task tool use pauses that run,
+ * executes the requested child agent, then starts a new turn for the parent
+ * with the child result in its context. Keeping the active agent IDs in
+ * delegationPath makes recursive delegation safe.
+ */
+async function* executeAgentConversation(
+  agentId: string,
+  request: ChatRequest,
+  abortController: AbortController,
+  debugMode: boolean,
+  delegationPath: string[],
+  streamText: boolean,
+  result: DelegationResult,
+): AsyncGenerator<StreamResponse> {
+  const provider = globalRegistry.getProviderForAgent(agentId);
+  const agentConfig = globalRegistry.getAgent(agentId);
+
+  if (!provider || !agentConfig) {
+    result.isError = true;
+    result.content = `Agent '${agentId}' not found or provider not available`;
+    return;
+  }
+
+  const context: ProviderContext[] = [];
+  let toolSequence = 0;
+
+  while (!result.isError) {
+    let delegated = false;
+    try {
+      const providerRequest: ProviderChatRequest = {
+        message: request.message,
+        sessionId: request.sessionId,
+        requestId: request.requestId,
+        workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
+        ...(context.length > 0 ? { context } : {}),
+      };
+
+      for await (const response of provider.executeChat(providerRequest, {
+        debugMode,
+        abortController,
+        temperature: agentConfig.config?.temperature,
+        maxTokens: agentConfig.config?.maxTokens,
+      })) {
+        if (response.type === "tool_use" && response.toolName === "delegate_task") {
+          const toolInput = response.toolInput as { agent_id?: unknown; instructions?: unknown } | undefined;
+          const targetAgentId = typeof toolInput?.agent_id === "string" ? toolInput.agent_id : "";
+          const instructions = typeof toolInput?.instructions === "string" ? toolInput.instructions : "";
+          const toolUseId = response.toolUseId || `${agentId}-delegate-${++toolSequence}`;
+
+          yield {
+            type: "claude_json",
+            data: { type: "tool_use", id: toolUseId, name: "delegate_task", input: response.toolInput },
+          };
+
+          let childResult: DelegationResult;
+          if (!targetAgentId || !globalRegistry.getAgent(targetAgentId) || !globalRegistry.getProviderForAgent(targetAgentId)) {
+            childResult = {
+              isError: true,
+              content: `Agent '${targetAgentId || String(toolInput?.agent_id)}' not found or provider not available`,
+            };
+            yield { type: "error", error: childResult.content };
+          } else if (delegationPath.includes(targetAgentId)) {
+            childResult = {
+              isError: true,
+              content: `Circular delegation detected: ${[...delegationPath, targetAgentId].join(" -> ")}`,
+            };
+            yield { type: "error", error: childResult.content };
+          } else {
+            childResult = { content: "", isError: false };
+            const childRequest: ChatRequest = { ...request, message: instructions };
+            yield* executeAgentConversation(
+              targetAgentId,
+              childRequest,
+              abortController,
+              debugMode,
+              [...delegationPath, targetAgentId],
+              false,
+              childResult,
+            );
+            if (!childResult.isError && !childResult.content) {
+              childResult.content = EMPTY_DELEGATION_RESULT;
+            }
+          }
+
+          const toolResult = {
+            type: "tool_result",
+            is_error: childResult.isError,
+            content: childResult.content,
+            tool_use_id: toolUseId,
+          };
+          const serializedToolResult = JSON.stringify(toolResult);
+          yield { type: "claude_json", data: toolResult };
+
+          // The next turn is deliberately a new provider invocation: providers
+          // expose one-way streams, so this is how the delegating agent receives
+          // the result and can decide what to do next.
+          context.push(
+            { role: "assistant", content: JSON.stringify({ type: "tool_use", id: toolUseId, name: "delegate_task", input: response.toolInput }) },
+            { role: "user", content: serializedToolResult },
+          );
+          delegated = true;
+          break;
+        }
+
+        if (response.type === "text") {
+          result.content += response.content || "";
+          if (streamText) {
+            const chatRoomMessage = createChatRoomMessage(response, agentId);
+            if (chatRoomMessage) {
+              yield { type: "claude_json", data: { type: "chat_room_message", message: chatRoomMessage, session_id: request.sessionId } };
+            }
+            yield { type: "claude_json", data: { type: "assistant", content: response.content, model: response.metadata?.model } };
+          }
+        } else if (response.type === "error") {
+          result.isError = true;
+          result.content = response.error || "Agent execution failed";
+          return;
+        } else if (response.type === "done") {
+          return;
+        }
+      }
+    } catch (error) {
+      result.isError = true;
+      result.content = error instanceof Error ? error.message : String(error);
+      return;
+    }
+
+    if (!delegated) return;
+  }
+}
